import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeFeature } from "../types/home";

type FeaturesProps = {
  items?: HomeFeature[];
};

export default function Features({ items = [] }: FeaturesProps) {
  if (!items.length) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 }, backgroundColor: "#fff" }}>
      <Container maxWidth="lg">
        <Stack spacing={8}>
          {items.map((item, index) => {
            const image = mediaUrl(item.image);
            const imageFirst = index % 2 === 1;
            return (
              <Stack
                key={item.id || item.title}
                direction={{ xs: "column", md: imageFirst ? "row" : "row-reverse" }}
                alignItems="center"
                spacing={4}
              >
                <Box sx={{ flex: 1 }}>
                  <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 1.5 }}>
                    {item.title}
                  </Typography>
                  <BlocksText
                    content={item.description}
                    sx={{ color: "#5a6473", fontSize: 16, lineHeight: 1.65 }}
                  />
                </Box>
                {image ? (
                  <Box sx={{ flex: 1, textAlign: "center" }}>
                    <Box
                      component="img"
                      src={image}
                      alt={item.image?.alternativeText || item.title}
                      sx={{ width: "100%", maxWidth: 480 }}
                    />
                  </Box>
                ) : null}
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
